		const les = one(g.lessons, lessonId);
		if (!les) return;
		const guest = g.makeups.find((m) => m.target_lesson_id === lessonId && m.student_id === studentId && m.status === "confirmed");
		const enr = guest ? one(g.enrollments, guest.enrollment_id) || enrollOf(g, studentId, one(g.lessons, guest.source_lesson_id)?.class_id || "") : enrollOf(g, studentId, les.class_id);
		let a = attOf(g, lessonId, studentId);
